test("maps ordinary language and goal-only entry into the bounded v1 DSL",()=>{assert.equal(outcome.idea.dsl.version,"strategy-dsl-v1");assert.ok(outcome.idea.dsl.factors.some(item=>item.id==="momentum_60"));assert.ok(outcome.idea.dsl.factors.some(item=>item.id==="low_volatility_20"));assert.equal(outcome.goal.dsl.research_goal,"lower_drawdown");assert.equal(outcome.goal.starting_points.length,3);assert.equal(outcome.goal.selected_starting_point_id,"low_volatility");assert.equal(outcome.goalTrend.selected_starting_point_id,"trend_low_volatility");assert.ok(outcome.goalTrend.dsl.factors.some(item=>item.id==="trend_ma20_60"));assert.equal(outcome.goal.planner,"rule_fallback");assert.equal(outcome.idea.dsl.allow_live_order,false)});
test("keeps an explicitly requested simple-hold reference instead of silently replacing it",()=>{assert.equal(outcome.explicitReference.gate,"goal_relative_equal_weight");assert.equal(outcome.explicitReference.standard.benchmark_strategy_id,"benchmark-equal");assert.match(outcome.explicitReference.standard.benchmark_name,/等权持有/);assert.match(outcome.explicitReference.standard.rule,/用户明确指定的同股票样本等权持有/);assert.ok(outcome.explicitReference.plainRules.some(rule=>/固定参照：同股票样本等权持有/.test(rule)))});
test("shares candidate deduplication across budgets without reusing a smaller sealed result",()=>{assert.equal(outcome.searchPolicyLedgerShared,true);assert.equal(outcome.searchPolicyRunSeparated,true)});
test("rejects arbitrary code and every unknown nested DSL enum",()=>{assert.equal(outcome.unknown.valid,false);assert.match(outcome.unknown.errors.join(" "),/不允许的字段|目录外因子/);assert.equal(outcome.badFrequency.valid,false);assert.equal(outcome.badWeight.valid,false);assert.ok(outcome.nestedInvalid.every(item=>item.valid===false))});
test("caps, explains, and de-duplicates the bounded parameter grid",()=>{assert.equal(outcome.candidates.length,outcome.idea.research_settings.candidate_budget);assert.equal(outcome.idea.research_settings.max_rounds,1);assert.ok(outcome.candidates.every(item=>item.thesis&&item.thesis!==outcome.idea.dsl.thesis_plain))});
test("runs the full bounded batch instead of stopping after a small proposal set",()=>{assert.equal(outcome.configured.settings.candidate_budget,100);assert.equal(outcome.configured.settings.target_candidates,2);assert.equal(outcome.configured.settings.search_mode,"exhaust_budget");assert.equal(outcome.configured.run.settings.search_mode,"exhaust_budget");assert.equal(outcome.configured.universe.id,"cn-a-non-financial-17");assert.equal(outcome.configured.maxPositions,4);assert.equal(outcome.configured.run.generated,100);assert.equal(outcome.configured.run.rounds.length,2);assert.equal(outcome.configured.run.audit.requested_symbols,17);assert.match(outcome.configured.run.standard.rule,/优于目标相关的最佳传统方法/);assert.equal(outcome.configured.run.rounds.at(-1).stopped,true);for(const benchmark of outcome.configured.benchmarkRules){assert.deepEqual(benchmark.universe,outcome.configured.universe);assert.equal(benchmark.maxPositions,4)}});
